  function esc(value) {
    return String(value).replace(/[&<>"']/g, character => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]));
  }
  function rotatePoint(point,pivot,degrees) {
    const radians=degrees*Math.PI/180,cos=Math.cos(radians),sin=Math.sin(radians),x=point.x-pivot.x,y=point.y-pivot.y;
    return {x:pivot.x+x*cos-y*sin,y:pivot.y+x*sin+y*cos};
  }
